insert into b2b_training_modules (slug, title, description, pass_pct, content) values ('ja102', 'JA102: Sales Training — STAR & Customer Types', 'From quote-takers to decision guides: this program tightens up the STAR framework and the four customer types at exactly the points a recent call-quality review found them breaking down, then wraps a recurring monthly workshop cycle around them so the change doesn''t fade after one session.', 90, '{"sections": [{"title": "Why This Program Exists", "intro": "The call-quality review that prompted this program: most calls scored 3–4 out of ten, and the habits behind that — the quote-taker pattern, no budget conversation, low curiosity and assumed mechanical literacy — get named here before they get fixed.", "slides": [1, 2]}, {"title": "From Quote-Taker to Decision Guide — The 4 Customer Types", "intro": "The identity shift at the heart of the program — a quote is not the finish line, a decision is — plus the RED, YELLOW, GREEN and BLUE customer types and how to spot and handle each within the first 30 seconds.", "slides": [3]}, {"title": "The STAR Framework, Reinforced", "intro": "The opening sequence (context before permission, every call) and the gap-fix for each STAR step — Situation curiosity, the Target budget question, plain-language Approach and a Result that always locks in a next step — worked through on a 2018 Hilux towing scenario.", "slides": [4, 5]}, {"title": "Vocal Presence, Phrases Library & Call Scoring", "intro": "Body language and its phone equivalent (pace, pauses, matching energy to type), the key questions and phrases mapped to each STAR step, and the 0–2 per-criterion scoring rubric that keeps every call comparable to the 3–4/10 baseline.", "slides": [6, 7, 8]}, {"title": "Kickoff Session — Team Call Review & the Perfect Call", "intro": "The one-off Friday launch session: score two real recorded calls together against the rubric, then hear the full model script — initial enquiry and follow-up — so everyone leaves with a concrete 10/10 reference point, not an abstract standard.", "slides": [9, 10, 11, 12]}, {"title": "The Monthly Workshop Cycle — Workshops 1 to 6", "intro": "Six ready-to-run monthly workshops, each closing one STAR gap in sequence: the budget conversation, curiosity-led discovery, plain English, handling hesitation, follow-up calls that convert, and full-team scoring calibration — then the cycle repeats with fresh calls.", "slides": [13, 14, 15, 16, 17]}, {"title": "Keeping It Alive — Cadence, Rollout & Role-Play", "intro": "The manager''s weekly-to-quarterly cadence that stops the training fading, the 30/60/90-day rollout plan, the metrics worth tracking, and the appendix of role-play scenarios to rotate through each cycle.", "slides": [18, 19]}], "questions": [{"q": "In the recent review of recorded sales calls that prompted this program, how were the majority of calls rated out of ten?", "options": ["Five to six out of ten", "Three to four out of ten", "One to two out of ten", "Seven to eight out of ten"], "correct": 1, "explain": "The review rated the majority of calls at three to four out of ten — and the call scoring rubric uses the same scale, so progress can be tracked apples-to-apples against that baseline.", "slide": 2}, {"q": "The review flagged one gap as the single biggest across every call reviewed. What was it?", "options": ["Advisors talked over customers instead of listening", "Advisors forgot to confirm the vehicle''s model and year", "Follow-up calls were never made after a quote went out", "Not one advisor ever asked about budget or pricing expectations"], "correct": 3, "explain": "Across every call reviewed, not one advisor asked whether the customer had a budget in mind or a pricing expectation. The manual calls this a gap in the Target step of STAR, not a missing skill.", "slide": 2}, {"q": "According to the decision-guide shift, what is the real finish line of a sales call?", "options": ["A decision — sending a quote and going quiet is a failure state, not a neutral outcome", "A quote emailed to the customer the same day", "A completed vehicle inspection booking", "A five-star review request"], "correct": 0, "explain": "The manual is blunt about it: a quote is not the finish line, a decision is. Sending a quote and going quiet is a failure state every advisor should feel in their gut before they hang up.", "slide": 3}, {"q": "The manual says most of the team are acting like they''ve been in a relationship with the customer for fifteen years. What mindset does it recommend instead?", "options": ["Treat it like a long marriage — familiarity builds trust", "Treat every call as a quick transaction and keep it brief", "Treat every call like the first few dates — genuinely curious about this specific person''s situation", "Treat every caller as an expert who already knows exactly what they want"], "correct": 2, "explain": "The fix for low curiosity and broad assumptions is to treat every call more like the first few dates than a long marriage — genuinely curious about this specific person, not running on autopilot because \"we''ve done a thousand of these\".", "slide": 2}, {"q": "How quickly should an advisor aim to identify which of the four customer types they''re talking to?", "options": ["By the end of the first call", "Ideally within the first 30 seconds", "Within the first five minutes", "Only once the quote has been sent"], "correct": 1, "explain": "Identifying the customer type early — ideally within the first 30 seconds — and adjusting your approach to match is what separates a conversion from a lost lead.", "slide": 3}, {"q": "A caller is direct and impatient and says \"just tell me — what''s the best option?\" Per the customer-type model, how do you handle them?", "options": ["Be direct, skip the fluff, give the recommendation and move to booking", "Slow right down, offer reassurance and mention other happy customers", "Send through a detailed spec comparison so they can weigh everything up", "Match their energy, paint the lifestyle vision, then anchor it with a date"], "correct": 0, "explain": "That''s a RED — Dominant buyer. RED buyers don''t want options, they want answers: be direct, skip the fluff, give the recommendation and move to booking. Reassurance suits GREEN, data suits BLUE and vision-painting suits YELLOW.", "slide": 3}, {"q": "A caller is energetic and expressive, talking non-stop about the build and the trips they''re planning. What''s the right play for this YELLOW buyer?", "options": ["Bring the data and technical reasons so the decision is provably correct", "Rein the energy in and steer them back to the practical facts", "Be patient, build trust slowly and confirm every step", "Match their energy, paint the vision — then anchor it with a date"], "correct": 3, "explain": "YELLOW — Influencing buyers buy the dream, so don''t wake them up: match their energy, paint the vision, then anchor it with a date so the excitement turns into a booking.", "slide": 3}, {"q": "A cautious caller keeps asking \"is it safe?\" and \"what do other people usually do?\" How does the model say to handle this GREEN buyer?", "options": ["Give one direct recommendation and push straight to booking", "Send comprehensive specs and comparisons and let them decide", "Be patient, build trust, reference other happy customers and confirm every step", "Skip the small talk — they want answers, not reassurance"], "correct": 2, "explain": "GREEN — Steady buyers want to be looked after: be patient, build trust, reference other happy customers and confirm every step. Pushing them like a RED or burying them in specs like a BLUE loses them.", "slide": 3}, {"q": "A caller asks for specs, comparisons and the technical reasons behind your recommendation. What matters most for this BLUE buyer?", "options": ["Anchoring the dream with a booking date as early as possible", "Bringing the data, giving reasons and not rushing the decision", "Referencing what other customers in their situation usually do", "Keeping the call short, direct and results-focused"], "correct": 1, "explain": "BLUE — Conscientious buyers buy when the decision is correct, not convenient: bring the data, give reasons and don''t rush them. Social proof suits GREEN, pace and directness suit RED.", "slide": 3}, {"q": "You''re about to ring a customer to follow up a quote. Per the opening sequence, which opener is correct?", "options": ["\"Hi, is now a bad time?\" — then explain who you are once they say it''s fine", "\"Hi Dave, quick one — have you made a decision yet?\"", "\"Hi Dave, it''s Ryan from Just Autos calling — just following up on your quote for your 300 Series. Is now a bad time?\"", "\"Hi Dave, sorry to bother you — have you got a minute?\""], "correct": 2, "explain": "The opening sequence never varies: greet and identify yourself and the business, give specific context about why you''re calling, and only then ask permission. Context always comes before \"is now a bad time?\" — asking it first puts the customer on the back foot.", "slide": 4}, {"q": "Where does the budget question belong in the STAR framework?", "options": ["In the Target step — confirming the outcome and confirming the budget are the same step", "In the Situation step, straight after the vehicle details", "In the Result step, once the customer has hesitated on price", "It''s only asked if the customer raises price first"], "correct": 0, "explain": "The budget question lives in the Target step: \"so the goal is [outcome], and keeping it safe long-term — and have you got a budget in mind for getting there?\" Skipping it is the single biggest gap the review found.", "slide": 4}, {"q": "In the Approach step, how do you know a technical explanation has the right amount of detail?", "options": ["It uses the correct acronyms — EGR, DPF — so the customer trusts your expertise", "It covers every component in the package at least once", "It takes less than a minute to deliver", "It can be tied to \"here''s what this means for you and your car\" — otherwise it''s the wrong amount of detail"], "correct": 3, "explain": "The Approach gap-fix is to explain in language anyone could follow, never assuming mechanical literacy. If an explanation can''t be tied to \"here''s what this means for you and your car\", it''s the wrong amount of detail — and always check understanding before moving on.", "slide": 5}, {"q": "A customer says \"I''ve got a decision to make — I need to think about it.\" Per the framework, what''s the strongest response?", "options": ["\"Yeah, totally understand — there''s a lot to process. I''ll email that through.\"", "\"No worries at all, take all the time you need.\"", "\"Totally get that — what do you feel like you most need to sort through to land on a decision?\"", "\"What if I knocked a bit off the price if you book today?\""], "correct": 2, "explain": "Sympathy alone (\"I understand, there''s a lot to process\") is the pattern the review flagged — it doesn''t move anything forward. The framework meets hesitation with curiosity about what''s blocking the decision, then locks in a concrete next step either way.", "slide": 7}, {"q": "You''ve just asked the budget question and the customer goes quiet. What does the vocal-presence guidance say to do?", "options": ["Jump in with a package suggestion so it isn''t awkward", "Leave a real pause — filling the silence for the customer undoes the question", "Repeat the question a little louder in case they missed it", "Move on and circle back to budget at the end of the call"], "correct": 1, "explain": "On the phone, pauses do the work body language does in person: leave a real pause after asking about budget or after a hesitation, because filling the silence for the customer undoes the question. Slow down on the Target and budget questions — rushing signals discomfort.", "slide": 6}, {"q": "How is the call scoring rubric structured?", "options": ["Five STAR-mapped criteria scored 0–2 each, giving a total out of ten", "Ten criteria scored 0–1 each, giving a total out of ten", "A single overall impression mark out of ten", "Four criteria — one per STAR letter — scored out of 2.5 each"], "correct": 0, "explain": "The rubric has five criteria mapped to STAR — Situation & curiosity, Target & budget, Approach & plain language, Result: decision support, and Result: concrete close — each scored 0–2 for a total out of ten, directly comparable to the 3–4/10 baseline.", "slide": 8}, {"q": "During the kickoff session''s team call reviews, why does the manager reveal their own score last?", "options": ["So the manager can adjust their score to match the room", "Because the manager''s score is the only one officially recorded", "To save time — scores are only compared if there''s a disagreement", "So the room doesn''t just anchor to the manager''s score — everyone scores independently and silently first"], "correct": 3, "explain": "Everyone scores each call independently and silently against the rubric first — about two minutes, on paper, no talking — then compares as a group. The manager reveals their score last so the room doesn''t just anchor to it. The goal is a shared, honest sense of what good sounds like, not catching anyone out.", "slide": 9}, {"q": "What is the five-step follow-up call structure taught in Workshop 5?", "options": ["Greet, quote, discount, objection-handle, close", "Open, probe, present, pressure, close", "Open, reference, reconfirm, reinforce, close", "Situation, Target, Approach, Result, Review"], "correct": 2, "explain": "The follow-up structure is: open with context then permission, reference the previous call, reconfirm the need, reinforce the solution, and close with a specific booking date — never an open question. Follow-ups are confident and direct, never apologetic or vague.", "slide": 16}, {"q": "Under the manager''s cadence, what must a new hire complete before taking live calls solo?", "options": ["Part 1 of the manual plus Workshops 1–2, followed by a 30-day shadowed and scored ramp period", "The full six-workshop cycle from start to finish", "A quarterly session with the business advisor", "Ten scored role-plays at eight out of ten or better"], "correct": 0, "explain": "New hires complete Part 1 and Workshops 1–2 before taking live calls solo, then do a 30-day shadowed and scored ramp period — this stops old quote-taker habits re-entering the team through new hires.", "slide": 18}]}'::jsonb) on conflict (slug) do update set title = excluded.title, description = excluded.description, pass_pct = excluded.pass_pct, content = excluded.content, updated_at = now();